CREATE TABLE "frozen_cost_config" (
	"organization_id" uuid NOT NULL,
	"scenario_id" uuid NOT NULL,
	"overhead_pct" numeric(5,2) NOT NULL,
	"buffer_pct" numeric(5,2) NOT NULL,
	"net_annual_hours" integer NOT NULL,
	"calendar_working_hours" numeric(8,3) NOT NULL,
	CONSTRAINT "frozen_cost_config_pkey" PRIMARY KEY("organization_id","scenario_id"),
	CONSTRAINT "frozen_cost_config_overhead_pct_check" CHECK ("overhead_pct" >= 0),
	CONSTRAINT "frozen_cost_config_buffer_pct_check" CHECK ("buffer_pct" >= 0),
	CONSTRAINT "frozen_cost_config_hours_check" CHECK (net_annual_hours > 0 and net_annual_hours <= calendar_working_hours)
);
