CREATE TABLE "frozen_rates" (
	"organization_id" uuid NOT NULL,
	"scenario_id" uuid NOT NULL,
	"category_id" uuid NOT NULL,
	"fully_loaded_annual_cost" numeric(12,2),
	"manual_cost_per_hour" numeric(12,2),
	"sell_rate" numeric(12,2) NOT NULL,
	CONSTRAINT "frozen_rates_pkey" PRIMARY KEY("organization_id","scenario_id","category_id"),
	CONSTRAINT "frozen_rates_cost_check" CHECK ((fully_loaded_annual_cost is null) <> (manual_cost_per_hour is null)),
	CONSTRAINT "frozen_rates_fully_loaded_annual_cost_check" CHECK ("fully_loaded_annual_cost" >= 0),
	CONSTRAINT "frozen_rates_manual_cost_per_hour_check" CHECK ("manual_cost_per_hour" >= 0),
	CONSTRAINT "frozen_rates_sell_rate_check" CHECK ("sell_rate" >= 0)
);
